sys_variable_value.value:
(function execute(inputs, outputs) {

    var grRitm = new GlideRecord('x_asscs_allos_o2c_requested_item');
    grRitm.get(inputs.id);


    var input = {
        propriedade: inputs.propriedade,
        codigoDisplay: inputs.codigoDisplay,
        shopping: inputs.shopping,
        area: inputs.area,
        classificacaoPropriedade: inputs.classificacaoPropriedade
    };

    var obj = {
        propriedade: '8d53f873877a1610f538edf80cbb358c',
        codigoDisplay: 'ffb7bee73bae1a904a3b3537f4e45a4e',
        shopping: '841c6fc81b74821075adb8481b4bcbc6',
        area: '0d3867041b74821075adb8481b4bcb3e',
        classificacaoPropriedade: 'd97d71e93bb2d6d04a3b3537f4e45a9c'
    };

    for (var key in obj) {


        if (obj.hasOwnProperty(key)) {

            var aux = criarQuestion(obj[key], input[key], grRitm.getTableName(), grRitm.getUniqueValue());

            var mrvs = new GlideRecord('sc_multi_row_question_answer');
            mrvs.initialize();
            mrvs.variable_set = 'd6c7a7c01b74821075adb8481b4bcb6c';
            mrvs.parent_table_name = grRitm.getTableName();
            mrvs.parent_id = grRitm.getUniqueValue();
            mrvs.row_index = '1';
            mrvs.item_option_new = obj[key];
            mrvs.value = input[key];
            mrvs.question_answer = aux;

            gs.info('item_option_new: ' + obj[key] + ', value: ' + input[key]);
            mrvs.insert();

        }
    }

    function criarQuestion(idQuestion, value, table, ritm) {
        var listQuestion = new GlideRecord("question_answer");
        
        listQuestion.initialize();
        listQuestion.question = idQuestion; //sys_id da question
        listQuestion.value = value;
        listQuestion.table_name = table;
        listQuestion.table_sys_id = ritm;
        var question = listQuestion.insert();
        return question;

    }

})(inputs, outputs);

